from product_ontology import compatibility,norm
from export_final_matcher_holdout import EXCLUSIONS,excluded_queries
P=ROOT/'data/matcher_final_cleanup';H=ROOT/'data/matcher_final_holdout'
def main():
 before=json.loads((P/'before_evaluation.json').read_text());after=json.loads((P/'after_evaluation.json').read_text());audit=json.loads((P/'root_causes.json').read_text());labels=list(csv.DictReader((ROOT/'data/matcher_structural_holdout/structural_holdout_assistant_labeled.csv').open()));originals={r['case_id']:r for r in csv.DictReader((ROOT/'data/matcher_structural_holdout/review.csv').open())}
 fields=[k for k in next(iter(originals.values())) if k not in ('review_label','reviewer','review_notes','failure_cause','wrong_family','prepared_food_false_positive','structurally_correct')]
 assert {r['case_id'] for r in labels}==set(originals) and len(labels)==1100
 assert all(all(r[k]==originals[r['case_id']][k] for k in fields) for r in labels)
 issues=list(csv.DictReader((ROOT/'data/matcher_structural_holdout/structural_holdout_assistant_issues.csv').open()));bylabel={r['case_id']:r for r in labels};assert len(issues)==86 and all(r==bylabel[r['case_id']] for r in issues)
 population=[json.loads(line) for line in (P/'after_population.jsonl').open()];byid={r['case_id']:r for r in population};service=ProductMatchService();regressions={r['case_id']:r for r in map(json.loads,(ROOT/'Model/evaluation/final_holdout_regressions.jsonl').open())};case_outcomes=[];hits=collections.Counter();fn_selected=0
 for case in audit['cases']:
  row=byid[case['case_id']];q,_=profile_from_query(case['ingredient_query'],service.overrides);reg=regressions[case['case_id']];pid=reg['product_feature']['product_id'];identity=service.identity_catalog.identities[pid];gate=compatibility(q.ontology,identity);old=case['before_query_ontology'];reasons=json.loads(case['reason_codes'])
  stage='A normalization' if case['case_id'] in ('59be81d599c6a938e23a','121a34769e13600961bc') else 'B ontology parsing' if old['family'] in (None,'prepared') or 'ambiguous_identity_or_variant' in reasons else 'D compatibility gate'
  outcome={k:case[k] for k in ('case_id','ingredient_query','review_label','selected_product','review_notes','root_cause','general_rule')};outcome.update(failure_stage_adjudicated=stage if case['review_label']=='SHOULD_HAVE_MATCHED' else case['failure_stage'],after_selected_product=(row['selected_match'] or {}).get('product_name'),after_reason_codes=row['reason_codes'],regression_reference_product=reg['product_name'],after_reference_gate_reasons=list(gate.reasons),expected_reference_compatible=reg['expected_allowed'],adjudication=reg['adjudication'],requires_new_selection_review=bool(row['selected_match']))
  if case['review_label']=='WRONG':outcome['original_wrong_pair_blocked']=not gate.allowed;outcome['assistant_label_disagreement']=case['root_cause']=='ASSISTANT_LABEL_DISAGREEMENT'
  else:
   allowed=service.identity_catalog.candidate_ids(q.ontology);retrieval=service.retriever.retrieve_product_candidates(q.normalized_signature,limit=20,use_semantic=True,allowed_product_ids=allowed);candidates=[c.product_id for c in retrieval.candidates];rank=candidates.index(pid)+1 if pid in candidates else None
   outcome['reference_rank']=rank;outcome['after_failure_stage']='D compatibility gate / unverified requirement' if not gate.allowed else 'C candidate retrieval' if not rank else 'E scoring / F threshold or material-margin abstention' if not row['selected_match'] else 'selected; new product requires review';fn_selected+=bool(row['selected_match'])
   for k in (5,10,20):hits[k]+=bool(rank and rank<=k)
  case_outcomes.append(outcome)
 old_controls=json.loads((ROOT/'data/matcher_structural_audit/root_causes.json').read_text())['random_correct_control_ids'];old_labels={r['case_id']:r for r in csv.DictReader((ROOT/'data/matcher_validation/review_assistant_labeled.csv').open())};old_outcomes={r['case_id']:r for r in before['outcomes']};controls=[]
 for cid in old_controls:
  if not old_outcomes[cid]['remains_abstained']:continue
  old=old_labels[cid];row=byid[cid];refs=[]
  if old['selected_product']:
   q,_=profile_from_query(old['ingredient_query'],service.overrides)
   for f in service.feature_by_id.values():
    if f['original_product_name']==old['selected_product']:refs.append(list(compatibility(q.ontology,service.identity_catalog.identities[f['product_id']]).reasons))
  controls.append({'case_id':cid,'query':old['ingredient_query'],'original_decision':old['current_matcher_decision'],'original_selected_product':old['selected_product'],'before_cleanup':'rejected','after_selected_product':(row['selected_match'] or {}).get('product_name'),'after_reason_codes':row['reason_codes'],'original_reference_gate_reasons':refs,'interpretation':'true lost accepted control' if old['current_matcher_decision']=='accepted' else 'already correctly rejected in original QA; not a lost accepted match'})
 assert len(controls)==12
 cheese=[r for r in labels if r['sample_group']=='hard: cheese'];cheese_changed=[r['case_id'] for r in cheese if (byid[r['case_id']]['selected_match'] or {}).get('product_name','')!=r['selected_product']]
 m=json.loads((H/'sample.json').read_text());fresh=list(csv.DictReader((H/'review.csv').open()));assert len(fresh)==len({norm(r['ingredient_query']) for r in fresh})==700;assert all(not r['review_label'] for r in fresh)
 overlaps={f:len({norm(r['ingredient_query']) for r in fresh}&excluded_queries(ROOT/f)) for f in EXCLUSIONS};assert not any(overlaps.values());assert all(hashlib.sha256((ROOT/f).read_bytes()).hexdigest()==h for f,h in m['source_hashes'].items());assert all(hashlib.sha256((ROOT/f).read_bytes()).hexdigest()==h for f,h in m['exclusion_sources'].items());assert hashlib.sha256((H/'review.csv').read_bytes()).hexdigest()==m['review_csv_sha256'];assert hashlib.sha256((H/'population.jsonl').read_bytes()).hexdigest()==m['population_sha256']
 verification={'count':700,'normalized_unique_queries':700,'blank_labels':True,'source_hashes_current':True,'population_and_csv_hashes_valid':True,'independent_overlap_counts':overlaps,'review_labels_match_original_holdout':True,'issues_match_labels':True}
 (P/'holdout_verification.json').write_text(json.dumps(verification,indent=2)+'\n');(P/'material_case_outcomes.json').write_text(json.dumps(case_outcomes,indent=2)+'\n');(P/'control_case_outcomes.json').write_text(json.dumps(controls,indent=2)+'\n')
 summary={'recommendation':'STRUCTURAL_ISSUES_REMAIN','label_provenance':'assistant QA, not independent human certification','new_manual_precision':None,'root_cause_counts':audit['wrong_root_cause_counts'],'new_regression_cases':68,'total_data_regression_cases':1944,'full_tests':487,'original_wrong_pairs_blocked':sum(r.get('original_wrong_pair_blocked',False) for r in case_outcomes),'label_disagreements':1,'formerly_rejected_FN_queries_now_accepted':fn_selected,'FN_reference_recall_proxy':{f'at_{k}':hits[k]/40 for k in (5,10,20)},'FN_reference_denominator':40,'cheese_selection_changes':cheese_changed,'controls':controls,'before':{k:v for k,v in before.items() if k not in ('outcomes','candidate_traces')},'after':{k:v for k,v in after.items() if k not in ('outcomes','candidate_traces')},'holdout':{k:v for k,v in m.items() if k not in ('cases','immutable_review_hashes')},'verification':verification}
 (P/'report.json').write_text(json.dumps(summary,indent=2)+'\n')
 lines=['# Final targeted structural cleanup','', '**STRUCTURAL_ISSUES_REMAIN**. One targeted cleanup is complete and a fresh blank holdout is ready. Do not freeze or certify success: new selections are unreviewed, benchmark proxies still fall short, and required inventory attributes remain unknown in some claimed false negatives.','', '## Evidence and root causes','', 'The supplied assistant QA files exactly match all 1,100 original holdout cases and immutable context; the 86-row issues file matches the labeled file. Counts: 853 CORRECT, 161 ACCEPTABLE_SUBSTITUTE, 28 WRONG, 40 SHOULD_HAVE_MATCHED, 18 AMBIGUOUS. These are assistant labels, not independent human gold. Original accepted-good rate was 608/636 = 95.60% (the supplied 95.44% was arithmetic-inconsistent); accepted WRONG was 28/636 = 4.40%; apparent rejected false-negative rate was 40/464 = 8.62%. Ambiguous labels are not counted correct.','', 'Every WRONG row was diagnosed before behavior edits; frozen diagnoses and code snapshots are in root_causes.json and *.before. One supplied WRONG label is disputed: “1 teaspoon cream of tartar” → cream of tartar is a genuine baking-acid identity. Its supplied label was preserved, and its regression expects compatibility.','', '| Structural cause | Rows |','|---|---:|']
 for cause,count in audit['wrong_root_cause_counts'].items():lines.append(f'| {cause} | {count} |')
 lines+=['','## General changes','', '- Purchased product heads now precede ingredient components for salsa, ketchup/catsup, mushroom sauce, pudding, cream of tartar and rendered bacon fat. Wine vinegar and wild rice remain distinct from generic forms. Seasoned beans preserve seasoning.','- Shortcake, bruschetta, baked-bean and meal/entree markers block component leakage. Flavored refrigerated gelatin has a distinct dessert identity. Cooked meat with unexplained nominal tokens and no verified brand/head metadata safely abstains; simply named cooked meat with verified branding remains possible. This conservative rule can reject legitimate underdocumented products.','- Named grocery identities (frankfurters, salami, seasoned salt, dressing, black tea, ginger-snap cookies, matzo meal, mixed vegetables and marshmallows) are purchasable identities, not blanket prepared negatives. Required flavors, meat species, dietary identity and cereal shape remain structural gates.','- Genuine plural/taxonomy gaps (cabbages, zucchinis, nutmeg, quinoa, linguine, cherries, capers, plantains, artichoke hearts and molasses) are covered. Explicit alternatives retain shared cereal/pudding/bean heads; a leading state in a multi-option list remains required on each option.','- Cheese hierarchy, species/cut gates, exact/substitute separation, retrieval implementation, score weights and global thresholds were preserved. Compatibility ranking code changed only its version tag; ontology and matcher version are now v3.1.','', '## Material cases and false-negative stages','', f'27 structurally wrong original product pairs are blocked; the remaining row is the cream-of-tartar label disagreement. All 68 material rows have a case_id, root cause, general rule and regression. There are 1,944 data regression cases in total and seven new test methods, including unseen-brand, purchased-food, required-variant and accepted-cheese controls.','', f'Of 40 SHOULD_HAVE_MATCHED queries, {fn_selected} now receive a selected product. This is recovery/coverage, not new manual correctness. Reference candidate recall@5/@10/@20: {hits[5]}/40, {hits[10]}/40, {hits[20]}/40; references are explicit evaluation anchors, not a perfect answer key. See material_case_outcomes.json for every normalization/ontology/gate diagnosis, post-fix candidate rank, selection, rejection reason and handling. No thresholds were lowered.','', 'Ten reference pairs still lack required evidence (canned state, tart-cherry identity, fresh state, skinless status, unsalted status or dried state). They have explicit safe-abstention regressions; no package-size/brand assumptions were used to manufacture missing attributes. A whole-chicken query now has an explicitly whole-chicken reference rather than accepting unspecified “Chicken”.','', '## Population before and after','', 'All 8,877 actual recipe queries were rerun. Precision/recall below use the frozen name-rule benchmark, not assistant/human gold.','', '| Metric | Before this pass | After |','|---|---:|---:|']
 def pct(x):return f'{100*x:.2f}%'
 for name,bv,av in [('Accepted',before['accepted'],after['accepted']),('Rejected',before['rejected'],after['rejected']),('No-match rate',pct(before['no_match_rate']),pct(after['no_match_rate']))]:lines.append(f'| {name} | {bv} | {av} |')
 for key,name in [('precision_proxy','Proxy precision'),('recall_proxy','Proxy recall'),('false_positive_rate_proxy','Proxy wrong / scored accepted'),('false_negative_rate_proxy','Proxy abstained positives / scored positives')]:lines.append(f'| {name} | {pct(before["top1_name_rule_proxy"]["all"][key])} | {pct(after["top1_name_rule_proxy"]["all"][key])} |')
 for key in ['wrong_family_count','prepared_food_fp','wrong_subfamily_count','wrong_species_cut','attribute_leakage','state_form_mistakes']:lines.append(f'| Top-1 proxy {key} | {before["top1_name_rule_proxy"]["all"][key]} | {after["top1_name_rule_proxy"]["all"][key]} |')
 for key in ['warm_uncached_median_ms','warm_uncached_p95_ms']:lines.append(f'| {key} | {before["latency"][key]:.3f} | {after["latency"][key]:.3f} |')
 lines+=['', f'Confidence distribution after: `{json.dumps(after["confidence_distribution"])}`. Accepted coverage increased by {after["accepted"]-before["accepted"]}; lower no-match rate was not achieved by rejecting more queries. Proxy recall nevertheless decreased; stricter real attributes and incomplete/name-rule labels do not justify hiding this result.','', f'After top-1 benchmark: {after["top1_name_rule_proxy"]["all"]["correct"]} correct / {after["top1_name_rule_proxy"]["all"]["accepted_scored"]} scored accepted; {after["top1_name_rule_proxy"]["all"]["wrong"]} flagged wrong and {after["top1_name_rule_proxy"]["all"]["ambiguous_or_unlabelled_product"]} selected products without labels. Unknowns are not counted correct; precision with unknowns counted as not correct is {pct(after["top1_name_rule_proxy"]["all"]["precision_including_unlabelled_as_not_correct_proxy"])}. Wrong-family/prepared proxy flags remain and must be adjudicated independently; do not claim zero actual errors.','', 'Latency uses the same 100 seeded, primed queries with matcher-result cache cleared per call; it excludes cold startup and end-to-end API overhead. Full family/confidence distributions, pair proxies and metrics are in report.json and after_evaluation.json.','', f'Cheese: {len(cheese_changed)} selected-product changes in the 23 assistant-good holdout rows; accepted cheese pairs also pass compatibility tests. The cheese top-1 proxy metrics are unchanged. This small sample does not certify 99% accuracy. Meat/cut precision proxy is {pct(after["top1_name_rule_proxy"]["meat"]["precision_proxy"])} and remains below 99%; no new manual accuracy is asserted.','', '## The 12 control cases','', 'Correction to the preceding report: 11 were already rejected and labeled CORRECT for rejecting in the original QA. They did not become abstentions after that QA. Only the frozen-vegetable OR query was originally accepted and then regressed. Each history was explicitly checked against the original CSV, rather than assuming CORRECT meant accepted.','', '| Case | Query | Original status | Current result |','|---|---|---|---|']
 for c in controls:lines.append(f'| {c["case_id"]} | {c["query"]} | {c["original_decision"]} | {c["after_selected_product"] or "; ".join(c["after_reason_codes"])} |')
 lines+=['', 'See control_case_outcomes.json for original product and compatibility reasons. The true lost accepted control is restored through shared-state OR parsing. Previously appropriate rejections were not forced back into acceptance.','', '## Fresh mini-holdout','', 'data/matcher_final_holdout/review.csv contains 700 cases, all labels blank, seed 20261011: 300 accepted Exact/High, 200 rejected, 200 separate hard-category cases. Selection uses only fixed structural strata and a fixed RNG; no correctness labels influence sampling.','', '| Hard stratum | Requested | Sampled | Eligible pool |','|---|---:|---:|---:|']
 for group,v in m['sample_counts'].items():
  if group.startswith('hard: '):lines.append(f'| {group[6:]} | {v["requested"]} | {v["sampled"]} | {m["hard_available_counts"][group[6:]]} |')
 lines+=['', f'Quota shortfalls before redistribution: `{json.dumps(m["hard_quota_shortfalls_before_redistribution"])}`. Scarcity is retained transparently rather than recycling historical cases.','', 'Independent verification found zero normalized-query overlap with old 950 QA, current 1,100 holdout, all three regression corpora, real-recipe regressions, historical harvest and inventory benchmark. Quantities are retained; this is case-level query disjointness, not independent food concepts or ontology rules. Source/exclusion hashes, CSV/population fingerprints, 700 normalized unique queries and blank labels were checked (holdout_verification.json).','', 'Review with `.venv/bin/python scripts/review_matcher_human.py --directory data/matcher_final_holdout`. No new sample labels or manual precision/false-negative estimates were generated.','', '## Validation and scope','', 'Full suite: **487/487 passing** (full_tests.log). `git diff --check` passes. Matcher internals, matcher tests and evaluation artifacts only were changed in this pass; existing unrelated local edits were preserved. No staging, commit, push, stash, restore or revert.','', '**STRUCTURAL_ISSUES_REMAIN**: await a new review, adjudicate unsupported assistant claims and remaining proxy flags; current evidence does not certify the requested precision, zero-family/prepared-error or meat/cut targets. Stop after this one cleanup pass.']
 (P/'report.md').write_text('\n'.join(lines)+'\n');print(json.dumps({k:summary[k] for k in ['recommendation','original_wrong_pairs_blocked','formerly_rejected_FN_queries_now_accepted','FN_reference_recall_proxy','cheese_selection_changes']},indent=2))
